package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The rates for the grades on a sheet: listed and set. */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Rollups rollups;
    private final Audit audit;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final Dues dues;

    public RateService(RateRepository rates, SheetService sheets, Rollups rollups, Audit audit, PersonRepository people,
            ClaimRepository claims, Dues dues) {
        this.rates = rates;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
        this.people = people;
        this.claims = claims;
        this.dues = dues;
    }

    /**
     * What a candidate rate for a grade would change: how many OPEN and PENDING claims of people on
     * the grade (the grade in force on the claim's date) would show a different due, and the sum of
     * the differences (new due minus current due).
     */
    public record Preview(int count, BigDecimal diff) {
    }

    /**
     * Preview a candidate rate applied to a grade on every date, in place of the grade's rates;
     * nothing is saved and nothing is audited. A claim bound by a statement keeps its figure, and a
     * settled claim is not counted.
     */
    @Transactional(readOnly = true)
    public Preview preview(String sheetId, String grade, BigDecimal pct) {
        Dues.Basis current = dues.live(sheetId);
        List<Rate> candidate = new ArrayList<>(current.rates().stream()
                .filter(rate -> !rate.getGrade().equals(grade)).toList());
        candidate.add(new Rate(sheetId, grade, null, pct.setScale(2, RoundingMode.UNNECESSARY)));
        Dues.Basis previewed = new Dues.Basis(current.sheet(), candidate, current.inherited(), current.corrected());
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        int count = 0;
        BigDecimal diff = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !claim.getStatus().isOpen() || claim.getSettledDue() != null
                    || !grade.equals(person.gradeOn(claim.getDate()))) {
                continue;
            }
            BigDecimal was = dues.due(claim, grade, current);
            BigDecimal now = dues.due(claim, grade, previewed);
            if (was == null ? now == null : now != null && was.compareTo(now) == 0) {
                continue;
            }
            count++;
            diff = diff.add(orZero(now)).subtract(orZero(was));
        }
        return new Preview(count, diff.setScale(2, RoundingMode.UNNECESSARY));
    }

    private static BigDecimal orZero(BigDecimal value) {
        return value == null ? BigDecimal.ZERO : value;
    }

    /** The sheet's rates by grade. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
    }

    /**
     * Set the rate for a grade from a date (null: from the beginning of time), replacing any the
     * grade had from that same date, applying through a to-date (null: no end); a to-date before the
     * from-date is refused.
     */
    @Transactional
    public synchronized Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to,
            BigDecimal pct) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A rate's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId);
        Rollups.Rollup before = rollups.take(sheetId);
        BigDecimal percent = pct.setScale(2, RoundingMode.UNNECESSARY);
        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from)
                .orElseGet(() -> new Rate(sheetId, grade, from, percent));
        rate.setPct(percent);
        rate.setToDate(to);
        Rate saved = rates.saveAndFlush(rate);
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user
                + " grade=" + saved.getGrade() + " rate=" + saved.getPct().toPlainString()
                + (saved.getFromDate() != null ? " from=" + saved.getFromDate() : "")
                + (saved.getToDate() != null ? " to=" + saved.getToDate() : ""));
        rollups.audit(sheetId, user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.history.AsOfGuard;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /**
     * What the screen is told about a grade's rate; the percent with two decimals, and the date it
     * applies from (null: from the beginning of time) and through (null: no end).
     */
    public record RateView(String grade, String pct, LocalDate from, LocalDate to) {

        public static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getPct().toPlainString(), rate.getFromDate(),
                    rate.getToDate());
        }
    }

    /**
     * A rate as entered on the form: a percent of 0.00 or more with up to two decimals, and the date
     * it applies from (none: from the beginning of time) and through (none: no end).
     */
    public record RateForm(@NotNull @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String pct, LocalDate from,
            LocalDate to) {
    }

    /** The rate import box's text: lines of grade,rate,from,to. */
    public record ImportForm(@NotNull @Size(max = 200_000) String text) {
    }

    /** What the screen is told of a rate import: how many rates were set, and the sheet's rates after. */
    public record ImportView(int set, List<RateView> rates) {
    }

    private final RateService service;
    private final RateImportService imports;
    private final SheetHistory history;

    public RateController(RateService service, RateImportService imports, SheetHistory history) {
        this.service = service;
        this.imports = imports;
        this.history = history;
    }

    /**
     * The sheet's rates by grade, each grade's by from-date; a grade with no rate is not listed. With an
     * as-of date, as they stood at the end of it.
     */
    @GetMapping
    public List<RateView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) String asOf) {
        return history.views(sheetId, AsOfGuard.date(asOf)).map(SheetHistory.Views::rates)
                .orElseGet(() -> service.list(sheetId).stream().map(RateView::of).toList());
    }

    /**
     * The rates of the sheet's ancestors, nearest first (its parent's, then its parent's parent's, up to
     * three levels up), each sheet's by grade and from-date: what a grade with no rate in force on the
     * sheet falls back to. With an as-of date, each as it stood at the end of it.
     */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) String asOf) {
        return history.inherited(sheetId, AsOfGuard.date(asOf)).stream()
                .map(rates -> rates.stream().map(RateView::of).toList()).toList();
    }

    /**
     * Set the rate for a grade from a date (through a to-date, if given), replacing any it had from
     * that date; a to-date before the from-date is refused.
     */
    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid RateForm form) {
        return RateView.of(service.set(sheetId, SignedIn.name(user), grade, form.from(),
                form.to(), new BigDecimal(form.pct())));
    }

    /**
     * Set a rate per imported line, in order, each as the rate form would; nothing is set when any line
     * is refused.
     */
    @PostMapping("/import")
    public ImportView importRates(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid ImportForm form) {
        int set = imports.importRates(sheetId, SignedIn.name(user), form.text()).size();
        return new ImportView(set, service.list(sheetId).stream().map(RateView::of).toList());
    }

    /** What the screen is told of a rate preview: the claims whose due would change, and the sum of the differences. */
    public record PreviewView(int count, String diff) {
    }

    /**
     * How many OPEN and PENDING claims on a grade would show a different due were a candidate rate
     * applied to the grade on every date, and the sum of the differences; nothing is saved.
     */
    @GetMapping("/{grade}/preview")
    public PreviewView preview(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestParam @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String pct) {
        RateService.Preview preview = service.preview(sheetId, grade, new BigDecimal(pct));
        return new PreviewView(preview.count(), preview.diff().toPlainString());
    }
}
